<?php
require_once 'config.php';require_admin();expire_manual_requests();if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['close_group'])){$s=db()->prepare("UPDATE app_groups SET status='Failed' WHERE id=? AND status='Open'");$s->execute([(int)$_POST['close_group']]);flash('Group closed.');header('Location: admin.php');exit;}$groups=db()->query('SELECT g.*,(SELECT COUNT(*) FROM group_members gm WHERE gm.group_id=g.id) members,(SELECT COALESCE(SUM(o.price),0) FROM orders o WHERE o.group_id=g.id AND o.status=\'Active\') total FROM app_groups g ORDER BY g.id DESC')->fetchAll();$users=db()->query('SELECT id,name,email,roll_no,room_no,mobile,is_admin,created_at FROM users ORDER BY id DESC')->fetchAll();$pageTitle='Admin';require 'header.php';?><h1>Admin Dashboard</h1><h2>Groups</h2><div class="card tablewrap"><table><tr><th>Group</th><th>Hostel</th><th>App</th><th>Mode</th><th>Members</th><th>Total</th><th>Target</th><th>Status</th><th>Action</th></tr><?php foreach($groups as $g):?><tr><td>Group-<?=$g['id']?></td><td><?=e($g['hostel_name'])?></td><td><?=e($g['app_name'])?></td><td><?=e($g['source_mode'])?></td><td><?=$g['members']?></td><td>₹<?=e(number_format((float)$g['total'],2))?></td><td>₹<?=e(number_format((float)$g['target_threshold'],2))?></td><td><?=e($g['status'])?></td><td><a href="group.php?id=<?=$g['id']?>">View</a> <?php if($g['status']==='Open'):?><form class="inline" method="post"><input type="hidden" name="close_group" value="<?=$g['id']?>"><button class="danger">Close</button></form><?php endif;?></td></tr><?php endforeach;?></table></div><h2>Students</h2><div class="card tablewrap"><table><tr><th>Name</th><th>Roll</th><th>Room</th><th>Mobile</th><th>Email</th><th>Admin</th></tr><?php foreach($users as $u):?><tr><td><?=e($u['name'])?></td><td><?=e($u['roll_no'])?></td><td><?=e($u['room_no'])?></td><td><?=e($u['mobile'])?></td><td><?=e($u['email'])?></td><td><?=$u['is_admin']?'Yes':'No'?></td></tr><?php endforeach;?></table></div><?php require 'footer.php';?>
